import java.io.*;
import java.util.*;

public final class CF_630_D2_E_V1 {

    private static final boolean DEBUG = false;
    private static BufferedWriter out;
    private static InputReader in;

    private static void debug(Object... x) {
        if (DEBUG) {
            for (Object o : x) System.err.print(o + " ");
            System.err.println();
        }
    }

    private static void info(Object x) {
        System.out.println(x);
    }

    private static void write(Object x) {
        try {
            out.write(x.toString() + "\n");
        } catch (IOException e) {}
    }

    private static long modPow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    private static void solve() throws IOException {
        out = new BufferedWriter(new OutputStreamWriter(System.out));
        in = new InputReader(System.in);

        long n = in.readLong();
        long m = in.readLong();
        int L = in.readInt();
        int R = in.readInt();

        long MOD = 998244353L;
        long nm = n * m;
        long inv2 = modPow(2, MOD - 2, MOD);

        long diff = R - L + 1;
        long oddCount = diff / 2;
        long evenCount = diff - oddCount;

        long ans;
        if (nm % 2 == 1) {
            ans = modPow(diff, nm, MOD);
        } else {
            long a = diff;
            long b = Math.abs(evenCount - oddCount);
            long term1 = modPow(a, nm, MOD);
            long term2 = modPow(b, nm, MOD);
            ans = ((term1 + term2) % MOD * inv2) % MOD;
        }

        write(ans);
        out.close();
    }

    public static void main(String[] args) throws IOException {
        solve();
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0, len = 0;

        InputReader(InputStream stream) {
            in = stream;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                ptr = 0;
                len = in.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private void skipWhitespace() throws IOException {
            int c;
            while ((c = read()) != -1 && Character.isWhitespace(c)) {}
            ptr--;
        }

        public int readInt() throws IOException {
            skipWhitespace();
            boolean neg = false;
            int c = read();
            if (c == '-') {
                neg = true;
                c = read();
            }
            int val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return neg ? -val : val;
        }

        public long readLong() throws IOException {
            skipWhitespace();
            boolean neg = false;
            int c = read();
            if (c == '-') {
                neg = true;
                c = read();
            }
            long val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return neg ? -val : val;
        }
    }
}
